shader_type canvas_item;
render_mode unshaded;
#include "res://shaders/window_field.gdshaderinc"
uniform vec2 cast_dir=vec2(0.7,0.7);
uniform float cot_e=1.0;
uniform float strength=0.35;
// Set only for the departing actor's caster passes. Other room casters stay 1.
uniform float source_opacity=1.0;
uniform bool floor_clip=true;
uniform bool use_window=true;
uniform bool lamp_shadow=false;
uniform float penumbra_scale=1.0;
uniform float ground_y=950.0;
uniform float height_factor=0.6;
uniform vec2 source_origin=vec2(0.0);
uniform vec2 source_axis_x=vec2(1.0,0.0);
uniform vec2 source_axis_y=vec2(0.0,1.0);
// Home derivative: VERTEX is actual sprite-local geometry, independent of atlas UV.
uniform bool mesh_projection=false;
uniform bool soft_mesh_projection=false;
uniform vec2 projection_direction=vec2(0.0);
uniform float lift_height=0.0;
uniform vec4 texture_bounds=vec4(0.0,0.0,1.0,1.0);
varying vec2 world_pos;
varying vec2 source_world;
varying float source_height;
void vertex(){
    source_world=source_origin+source_axis_x*VERTEX.x+source_axis_y*VERTEX.y;
    source_height=max(ground_y-source_world.y,0.0);
    if(mesh_projection){
        float support_y=(round(COLOR.r*255.0)*256.0+round(COLOR.g*255.0))/16.0-2048.0;
        vec2 support=source_origin+source_axis_x*VERTEX.x+source_axis_y*support_y;
        support.y+=lift_height;
        if(soft_mesh_projection){support=vec2(source_world.x,support_y); }
        source_height=max(support.y-source_world.y,0.0);
        VERTEX=vec2(source_world.x,support.y)+projection_direction*source_height;
    }
    world_pos=(MODEL_MATRIX*vec4(VERTEX,0.0,1.0)).xy;
}
float inside_source(vec2 uv){
    return step(texture_bounds.x,uv.x)*step(texture_bounds.y,uv.y)*step(uv.x,texture_bounds.z)*step(uv.y,texture_bounds.w);
}
vec2 clamped_source_uv(vec2 uv,vec2 texel){
    // Keep bilinear footprints within this atlas entry, including the half texel.
    return clamp(uv,texture_bounds.xy+texel*0.5,texture_bounds.zw-texel*0.5);
}
void fragment(){
    float h=source_height*height_factor;
    // Penumbra grows away from grounded contact, to avoid cut-paper blocks.
    vec2 d=TEXTURE_PIXEL_SIZE*(2.0+clamp(h*0.045,0.0,9.0))*penumbra_scale;
    float a=texture(TEXTURE,clamped_source_uv(UV,TEXTURE_PIXEL_SIZE)).a*inside_source(UV)*0.24;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(d.x,0.0),TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(d.x,0.0))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV-vec2(d.x,0.0),TEXTURE_PIXEL_SIZE)).a*inside_source(UV-vec2(d.x,0.0))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(0.0,d.y),TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(0.0,d.y))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV-vec2(0.0,d.y),TEXTURE_PIXEL_SIZE)).a*inside_source(UV-vec2(0.0,d.y))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV+d*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+d*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV-d*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV-d*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(d.x,-d.y)*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(d.x,-d.y)*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(-d.x,d.y)*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(-d.x,d.y)*0.707)*0.07;
    float g=min(window_field(world_pos,cast_dir,cot_e),window_field(source_world,cast_dir,cot_e));
    if(!use_window){g=1.0;}
    if(lamp_shadow){
        float r=length(world_pos-vec2(465.0,468.0))/672.0;
        float falloff=r<0.35?mix(1.0,0.45,r/0.35):mix(0.45,0.0,clamp((r-0.35)/0.65,0.0,1.0));
        g*=falloff;
    }
    if(floor_clip){g*=smoothstep(738.0,748.0,world_pos.y);}
    COLOR=vec4(0.10,0.075,0.055,a*strength*g*source_opacity);
}

